<section id="faq" class="section faq"><div class="container faq-grid"><div><p class="eyebrow"><?= site_copy('faq_label') ?></p><h2><?= site_copy('faq_title') ?><br><em><?= site_copy('faq_accent') ?></em></h2><p><?= copy_lines('faq_intro') ?></p><a class="text-link" href="<?=e(phone_url($c['phone']))?>"><?= site_copy('faq_phone') ?></a></div><div class="faq-list"><?php foreach($c['faq'] as $i=>$f): ?><details data-reveal <?=$i===0?'open':''?>><summary><span><?=e($f['question'])?></span><span class="faq-plus" aria-hidden="true">+</span></summary><p><?=e($f['answer'])?></p></details><?php endforeach; ?></div></div></section>
